export default {"file":"teacher-profile.html","title":"Staff Profile | Schoolix","htmlClass":"","bodyClass":"sx-admin-app sx-dark-portal","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n\r\n<main class=\"profile-shell\" id=\"profileShell\">\r\n  <section class=\"profile-hero card\">\r\n    <div class=\"hero-bg\"></div>\r\n    <div class=\"hero-main\">\r\n      <button type=\"button\" class=\"back-link\" id=\"profileBackButton\" onclick=\"goBackToRolePage()\">Back</button>\r\n      <div class=\"hero-identity\">\r\n        <button type=\"button\" class=\"teacher-photo-xl\" id=\"heroPhoto\" onclick=\"previewTeacherPhoto()\">T</button>\r\n        <div class=\"hero-copy\">\r\n          <span class=\"eyebrow\" id=\"profileRoleLabel\">Faculty Profile</span>\r\n          <h1 id=\"teacherName\">Loading profile...</h1>\r\n          <div class=\"hero-subline\">\r\n            <span id=\"teacherIdChip\">Staff ID</span>\r\n            <span id=\"teacherEmailChip\">Email</span>\r\n            <span id=\"teacherPhoneChip\">Phone</span>\r\n            <span class=\"status-badge status-active\" id=\"teacherStatusBadge\">Active</span>\r\n          </div>\r\n          <div class=\"hero-tags\" id=\"heroTags\"></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"hero-actions\">\r\n      <button type=\"button\" class=\"btn btn-primary\" onclick=\"openEditProfile()\">Edit Profile</button>\r\n      <button type=\"button\" class=\"btn btn-light\" id=\"generateQrAction\" onclick=\"generateTeacherQr()\">Generate QR</button>\r\n      <button type=\"button\" class=\"btn btn-light\" onclick=\"jumpToSection('attendanceSection')\">Attendance</button>\r\n      <button type=\"button\" class=\"btn btn-light\" onclick=\"jumpToSection('salarySection')\">Salary</button>\r\n      <button type=\"button\" class=\"btn btn-light\" onclick=\"printTeacherProfile()\">Print Profile</button>\r\n    </div>\r\n  </section>\r\n\r\n  <div id=\"globalStatus\"></div>\r\n\r\n  <section class=\"skeleton-grid\" id=\"skeletonState\" hidden aria-hidden=\"true\">\r\n    <div class=\"skeleton-card\"></div>\r\n    <div class=\"skeleton-card wide\"></div>\r\n    <div class=\"skeleton-card wide\"></div>\r\n  </section>\r\n\r\n  <section class=\"profile-layout\" id=\"profileContent\" hidden>\r\n    <aside class=\"sidebar-card card\">\r\n      <button type=\"button\" class=\"teacher-photo-lg\" id=\"sidebarPhoto\" onclick=\"previewTeacherPhoto()\">T</button>\r\n      <h2 id=\"sidebarName\">Loading profile...</h2>\r\n      <p id=\"sidebarDesignation\">Designation</p>\r\n      <div class=\"sidebar-summary\" id=\"sidebarSummary\"></div>\r\n    </aside>\r\n\r\n    <div class=\"content-stack\">\r\n      <section class=\"metric-grid\" id=\"metricGrid\"></section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Personal</span><h2>Personal Details</h2></div></div>\r\n        <div class=\"detail-grid\" id=\"personalDetails\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Professional</span><h2>Professional Details</h2></div></div>\r\n        <div class=\"detail-grid\" id=\"professionalDetails\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\">\r\n          <div><span class=\"kicker\">Identity</span><h2>Identity Documents</h2></div>\r\n        </div>\r\n        <div class=\"document-grid\" id=\"identityDocuments\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Payroll</span><h2>Bank Details</h2></div></div>\r\n        <div class=\"detail-grid\" id=\"bankDetails\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Safety</span><h2>Emergency Contact</h2></div></div>\r\n        <div class=\"detail-grid\" id=\"emergencyDetails\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\">\r\n          <div><span class=\"kicker\">Files</span><h2>Documents</h2></div>\r\n        </div>\r\n        <div class=\"document-grid\" id=\"profileDocuments\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\" id=\"salarySection\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Salary</span><h2>Salary History</h2></div></div>\r\n        <div class=\"table-wrap\"><table class=\"data-table\"><thead><tr><th>Month</th><th>Basic</th><th>Allowances</th><th>Deductions</th><th>Net</th><th>Paid</th><th>Remaining</th><th>Status</th><th>Payment Date</th><th>Receipt</th></tr></thead><tbody id=\"salaryRows\"></tbody></table></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\" id=\"attendanceSection\">\r\n        <div class=\"card-head\">\r\n          <div><span class=\"kicker\">Attendance</span><h2>Monthly Attendance Calendar</h2></div>\r\n          <div class=\"attendance-month-actions\">\n            <input type=\"month\" id=\"attendanceMonth\">\n            <button type=\"button\" class=\"btn btn-primary\" id=\"attendanceMonthShow\">Show</button>\n          </div>\n        </div>\r\n        <div class=\"calendar-wrap\" id=\"attendanceCalendar\"></div>\r\n        <div class=\"metric-grid compact\" id=\"attendanceMetrics\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Leaves</span><h2>Leave History</h2></div></div>\r\n        <div class=\"timeline\" id=\"leaveTimeline\"></div>\r\n      </section>\r\n\r\n      <section class=\"card detail-card\">\r\n        <div class=\"card-head\"><div><span class=\"kicker\">Activity</span><h2>Activity Timeline</h2></div></div>\r\n        <div class=\"timeline\" id=\"activityTimeline\"></div>\r\n      </section>\r\n    </div>\r\n  </section>\r\n</main>\r\n\r\n<div class=\"modal\" id=\"editModal\" hidden>\r\n  <div class=\"modal-panel\">\r\n    <div class=\"modal-head\">\r\n      <div><span class=\"kicker\">Edit</span><h2 id=\"editProfileTitle\">Edit Staff Profile</h2></div>\r\n      <button type=\"button\" class=\"icon-btn\" onclick=\"closeEditProfile()\" aria-label=\"Close edit profile\">x</button>\r\n    </div>\r\n    <form id=\"editProfileForm\" class=\"edit-form\">\r\n      <div class=\"form-tabs\" id=\"editTabs\"></div>\r\n      <div id=\"editFields\"></div>\r\n      <div class=\"modal-actions\">\r\n        <button type=\"button\" class=\"btn btn-light\" onclick=\"closeEditProfile()\">Cancel</button>\r\n        <button type=\"submit\" class=\"btn btn-primary\" id=\"saveProfileBtn\">Save Profile</button>\r\n      </div>\r\n    </form>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"modal\" id=\"detailModal\" hidden>\r\n  <div class=\"modal-panel small\">\r\n    <div class=\"modal-head\">\r\n      <div><span class=\"kicker\" id=\"detailKicker\">Details</span><h2 id=\"detailTitle\">Details</h2></div>\r\n      <button type=\"button\" class=\"icon-btn\" onclick=\"closeDetailModal()\" aria-label=\"Close details\">x</button>\r\n    </div>\r\n    <div id=\"detailBody\"></div>\r\n  </div>\r\n</div>\r\n\r\n<script src=\"school-branding.js\"></script>\r\n<script type=\"module\" src=\"teacher-profile.js\"></script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n<script src=\"schoolix-polish.js\" defer></script>\r\n<script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"href":"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap","rel":"stylesheet"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"teacher-profile.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-portal-dark.css"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module","src":"teacher-profile.js"},"text":""},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
